questions.answer:
class ValidationError extends Error {
  constructor(field, message) {
    super(message);
    this.name = "ValidationError";
    this.field = field;
  }
}

const parseUser = (input) => {
  if (!input || typeof input.name !== "string" || input.name.trim() === "") {
    throw new ValidationError("name", "Name is required");
  }
  if (!Number.isFinite(input.age) || input.age <= 0) {
    throw new ValidationError("age", "Age must be a positive number");
  }
  return { name: input.name.trim(), age: input.age };
};

console.log(parseUser({ name: "Kakade", age: 25 })); // { name: 'Kakade', age: 25 }

try {
  parseUser({ name: "Kakade", age: -1 });
} catch (err) {
  console.log(err.name, err.field, err.message);
}
// ValidationError age Age must be a positive number

The subclass must call super(message) before using this. Setting this.name makes logs and serialisation readable; without it the name inherits "Error". Number.isFinite rejects NaN, Infinity, and non-numbers in one check. Throwing on the first invalid field is fine for this exercise; a form validator would usually collect all field errors and return them together.

